?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalog Expansion | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}main{max-width:1400px;margin:auto;padding:28px}.controls,.cards{display:flex;gap:12px;flex-wrap:wrap}.card,.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px}.panel{margin-top:18px}select{padding:8px;border:1px solid #cbd5e1;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{padding:9px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:top;font-size:13px}.yes{color:#166534}.no{color:#b91c1c}.pill{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:11px}.muted{color:#64748b}.score{font-weight:800;font-size:16px}@media(max-width:900px){table{display:block;overflow:auto}}</style></head><body><main><h1>Evidence-led Catalog Expansion</h1><p class="muted">Prioritize research from real demand signals. Demand never overrides evidence readiness or publication gates.</p><div class="controls"><label>Window <select id="days"><option>30</option><option selected>90</option><option>180</option><option>365</option></select> days</label></div><section class="panel"><h2>Existing categories — expansion priority</h2><table><thead><tr><th>Category</th><th>Demand</th><th>Buyer signals</th><th>Search demand</th><th>Catalog</th><th>Evidence</th><th>Readiness</th><th>Action</th></tr></thead><tbody id="existing"></tbody></table></section><section class="panel"><h2>Uncovered taxonomy demand</h2><p class="muted">Topics already represented by an active category are excluded here.</p><table><thead><tr><th>Topic</th><th>Demand</th><th>Occurrences</th><th>Search demand</th><th>Latest example</th><th>Action</th></tr></thead><tbody id="missing"></tbody></table></section><section class="panel"><h2>Publication policy</h2><div id="policy" class="cards"></div></section></main><script>const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){let d=await fetch('/api/catalog-expansion?days='+days.value).then(r=>r.json());existing.innerHTML=(d.existing_categories||[]).map(x=>`<tr><td><strong>${e(x.name)}</strong><br><span class="pill">${e(x.slug)}</span></td><td class="score">${e(x.priority_score)}</td><td>${e(x.buyer_events)} events<br>${e(x.consultations)} consultations</td><td>${e(x.gsc_impressions)} impressions<br>${e(x.gsc_clicks)} clicks</td><td>${e(x.active_products)} active<br>${e(x.ready_products)} ready</td><td>${e(x.verified_sources)} verified sources<br>${e(x.evidence_coverage_pct)}% known facts<br>${e(x.avg_known_confidence??'—')}% confidence</td><td class="${x.publication_ready?'yes':'no'}">${x.publication_ready?'Ready':'Blocked'}</td><td>${e(x.recommended_action)}</td></tr>`).join('')||'<tr><td colspan="8">No data.</td></tr>';missing.innerHTML=(d.new_category_candidates||[]).map(x=>`<tr><td><strong>${e(x.topic_label)}</strong><br><span class="pill">/${e(x.proposed_slug)}</span></td><td class="score">${e(x.priority_score)}</td><td>${e(x.occurrence_count)}<br>${e(x.priority)}</td><td>${e(x.gsc_impressions)} impressions<br>${e(x.gsc_clicks)} clicks</td><td>${e(x.latest_example_request||'—')}</td><td>${e(x.recommended_action)}</td></tr>`).join('')||'<tr><td colspan="6">No uncovered taxonomy demand.</td></tr>';let p=d.policy||{};policy.innerHTML=`<div class="card">≥ ${e(p.minimum_active_products)} active products</div><div class="card">≥ ${e(p.minimum_ready_products)} ready products</div><div class="card">≥ ${e(p.minimum_verified_sources)} verified sources</div><div class="card">≥ ${e(p.minimum_known_capability_rows)} known capability rows</div><div class="card">Unknown ≠ Unsupported</div>`}days.onchange=load;load();</script></body></html>